package dev.queryable.snello.runtime;

import jakarta.inject.Inject;
import jakarta.ws.rs.core.Response;
import jakarta.ws.rs.core.UriInfo;

/**
 * Base class of the JAX-RS resources generated at build time. Each generated
 * resource contributes the snello collection {@code GET} endpoint, while the
 * remaining CRUD endpoints are generated by REST Data with Panache.
 */
public abstract class SnelloGeneratedResource<T> {

    @Inject
    SnelloEngine engine;

    private final Class<T> entityType;

    protected SnelloGeneratedResource(Class<T> entityType) {
        this.entityType = entityType;
    }

    protected Response listInternal(UriInfo uriInfo) {
        return engine.list(entityType, uriInfo);
    }
}
